const item = $input.item.json;
const shortlist = (item.playerSearch && Array.isArray(item.playerSearch.shortlist))
  ? item.playerSearch.shortlist
  : [];
const now = new Date().toISOString();

// Deterministischer Dummy je Kandidat. Es wird explizit keine echte
// Qlik-Analyse oder Websuche durchgefuehrt; jeder Eintrag ist klar als
// simulierte Dummy-Quelle gekennzeichnet.
const research = shortlist.map((candidate, idx) => ({
  candidate: candidate.name,
  club: `Dummy-Verein ${idx + 1}`,
  contract: 'Simulierter Vertrag bis 30.06.2027 (keine echte Recherche)',
  marketValue: `${(5 + idx).toFixed(1)} Mio. EUR (simuliert)`,
  injuries: 'Keine bekannten Verletzungen (simuliert, keine echte Recherche)',
  news: [`Simulierte Meldung zu ${candidate.name} (keine echte Websuche durchgefuehrt)`],
  source: 'Dummy-Quelle (keine echte Web-/Qlik-Recherche)',
  timestamp: now,
  confidence: 0.4
}));

return [{ json: { ...item, research } }];

const item = $input.item.json;

let agentResult = item.output !== undefined ? item.output : item;

if (typeof agentResult === 'string') {
  try {
    agentResult = JSON.parse(agentResult);
  } catch (e) {
    // Not valid JSON — pass through as-is.
  }
}

return { research: agentResult };
